test("tabela ma nazwę, właściwy link i brak przypisanego użytkownika",()=>{renderWithProviders(<TicketTable tickets={[makeTicket()]}/>);const table=screen.getByRole("table",{name:"Tickety zespołu"}),row=within(table).getByRole("row",{name:/API timeout/});expect(within(row).getByRole("link",{name:"API timeout"})).toHaveAttribute("href","/tickets/42");expect(row).toHaveTextContent("—");expect(within(row).getByRole("button",{name:"Zamknij"})).toBeEnabled();});test("closed wyłącza tylko akcję właściwego rekordu",()=>{renderWithProviders(<TicketTable tickets={[makeTicket({id:1,title:"Wyszukiwanie"}),makeTicket({id:2,title:"Dokumentacja",status:"CLOSED"})]}/>);expect(within(screen.getByRole("row",{name:/Dokumentacja/})).getByRole("button",{name:"Zamknij"})).toBeDisabled();expect(within(screen.getByRole("row",{name:/Wyszukiwanie/})).getByRole("button",{name:"Zamknij"})).toBeEnabled();});test("pending dotyczy konkretnego rekordu",()=>{renderWithProviders(<TicketTable tickets={[makeTicket({id:1,title:"Jeden"}),makeTicket({id:2,title:"Dwa"})]} pendingId={1}/>);expect(within(screen.getByRole("row",{name:/Jeden/})).getByRole("button")).toBeDisabled();expect(within(screen.getByRole("row",{name:/Dwa/})).getByRole("button")).toBeEnabled();});test("pusty stan nie udaje tabeli z rekordami",()=>{renderWithProviders(<TicketTable tickets={[]}/>);expect(screen.getByRole("status")).toHaveTextContent("Brak ticketów do wyświetlenia");expect(screen.queryByRole("table")).not.toBeInTheDocument();});test("callback otrzymuje id wybranego wiersza",async()=>{const user=userEvent.setup(),onClose=vi.fn();renderWithProviders(<TicketTable tickets={[makeTicket({id:1,title:"Jeden"}),makeTicket({id:2,title:"Dwa"})]} onClose={onClose}/>);await user.click(within(screen.getByRole("row",{name:/Dwa/})).getByRole("button"));expect(onClose).toHaveBeenCalledExactlyOnceWith(2);});test("nieaktywna akcja nie woła callbacku",async()=>{const user=userEvent.setup(),onClose=vi.fn();renderWithProviders(<TicketTable tickets={[makeTicket({status:"CLOSED"})]} onClose={onClose}/>);await user.click(screen.getByRole("button",{name:"Zamknij"}));expect(onClose).not.toHaveBeenCalled();});test("rerender odświeża status istniejącego rekordu",()=>{const ticket=makeTicket(),result=renderWithProviders(<TicketTable tickets={[ticket]}/>);result.rerender(<TicketTable tickets={[{...ticket,status:"CLOSED"}]}/>);expect(screen.getByRole("button",{name:"Zamknij"})).toBeDisabled();expect(screen.queryByText("Otwarty")).not.toBeInTheDocument();});

