// @vitest-environment jsdom
import {expect,test,vi} from "vitest";import {screen,within} from "@testing-library/react";import {renderWithProviders} from "./renderWithProviders";import {Breadcrumbs} from "./Breadcrumbs";import {TicketPreview} from "./TicketPreview";import {makeTicket} from "./ticketTypes";
test("okruszki odczytują realny kontekst routera",()=>{renderWithProviders(<Breadcrumbs/>,{route:"/settings/security"});const nav=screen.getByRole("navigation",{name:"Ścieżka"});expect(within(nav).getByRole("link",{name:"Ustawienia"})).toHaveAttribute("href","/settings");expect(within(nav).getByText("Bezpieczeństwo")).toHaveAttribute("aria-current","page");});test("fabryka tworzy niezależne dane tablicowe",()=>{const a=makeTicket(),b=makeTicket();a.tags.push("api");expect(b.tags).toEqual([]);});test("findBy czeka na dane z rzeczywistego providera zapytań",async()=>{const read=vi.fn().mockResolvedValue(makeTicket({title:"Wczytany ticket"}));const result=renderWithProviders(<TicketPreview id={42} read={read}/>);expect(await screen.findByRole("heading",{name:"Wczytany ticket"})).toBeVisible();expect(read).toHaveBeenCalledExactlyOnceWith(42);result.unmount();result.queryClient.clear();});test("nowy renderWithProviders nie dziedziczy cache innego testu",async()=>{const first=renderWithProviders(<TicketPreview id={42} read={async()=>makeTicket({title:"Pierwszy"})}/>);await screen.findByRole("heading",{name:"Pierwszy"});first.unmount();const second=renderWithProviders(<TicketPreview id={42} read={async()=>makeTicket({title:"Drugi"})}/>);expect(second.queryClient).not.toBe(first.queryClient);expect(await screen.findByRole("heading",{name:"Drugi"})).toBeVisible();first.queryClient.clear();second.unmount();second.queryClient.clear();});test("błąd zapytania pokazuje alert zamiast fałszywych danych",async()=>{const result=renderWithProviders(<TicketPreview id={42} read={async()=>{throw Error("niedostępne");}}/>);expect(await screen.findByRole("alert")).toHaveTextContent("Nie udało się pobrać ticketu.");expect(screen.queryByRole("heading")).not.toBeInTheDocument();result.unmount();result.queryClient.clear();});

